namespace sv_1e8c69debc7242e995fe0dd922328e23.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

namespace sv_1e8c69debc7242e995fe0dd922328e23.Services;

public class MockChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId = 100;

    public MockChatService()
    {
        _channels = new List<Channel>
        {
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering topics and code reviews", 0),
            new(3, "design", "UI/UX design discussions", 1),
            new(4, "random", "Off-topic conversations", 5),
            new(5, "announcements", "Important team announcements", 0),
        };

        _messages = new List<Message>
        {
            new(1, 1, "Alice", "Hey everyone! Welcome to the new team chat.", DateTime.UtcNow.AddHours(-5), null, new List<Reaction> { new("👋", new List<string> { "Bob", "Carol" }), new("🎉", new List<string> { "Dave" }) }),
            new(2, 1, "Bob", "Thanks Alice! Excited to be here.", DateTime.UtcNow.AddHours(-4), null, new List<Reaction>()),
            new(3, 1, "Carol", "Does anyone have the link to the design docs?", DateTime.UtcNow.AddHours(-3), null, new List<Reaction> { new("👍", new List<string> { "Alice" }) }),
            new(4, 1, "Alice", "Sure, I'll share it in the design channel.", DateTime.UtcNow.AddHours(-3).AddMinutes(5), 3, new List<Reaction>()),
            new(5, 1, "Dave", "The sprint planning is at 2pm today.", DateTime.UtcNow.AddMinutes(-45), null, new List<Reaction> { new("👀", new List<string> { "Alice", "Bob", "Carol" }) }),
            new(6, 1, "Bob", "I'll be there!", DateTime.UtcNow.AddMinutes(-30), 5, new List<Reaction>()),
            new(7, 1, "Carol", "Same here. Can we discuss the API changes?", DateTime.UtcNow.AddMinutes(-20), 5, new List<Reaction>()),
            new(8, 1, "Alice", "Has anyone reviewed PR #142?", DateTime.UtcNow.AddMinutes(-10), null, new List<Reaction>()),
            new(9, 1, "Dave", "Looking at it now.", DateTime.UtcNow.AddMinutes(-5), 8, new List<Reaction>()),
            new(10, 2, "Bob", "Just pushed the new API endpoint for user search.", DateTime.UtcNow.AddHours(-2), null, new List<Reaction> { new("🚀", new List<string> { "Alice", "Carol" }) }),
            new(11, 2, "Carol", "Nice work! I'll integrate it with the frontend.", DateTime.UtcNow.AddHours(-1), null, new List<Reaction>()),
            new(12, 3, "Dave", "Here are the new mockups for the dashboard.", DateTime.UtcNow.AddHours(-6), null, new List<Reaction> { new("😍", new List<string> { "Alice", "Bob" }), new("👍", new List<string> { "Carol" }) }),
        };
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        return Task.FromResult(_channels.ToList());
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var messages = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();
        return Task.FromResult(messages);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = Interlocked.Increment(ref _nextMessageId);
        var message = new Message(id, channelId, "You", content, DateTime.UtcNow, replyToId, new List<Reaction>());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        var replies = _messages.Where(m => m.ReplyToId == rootMessageId).OrderBy(m => m.SentAt).ToList();
        var result = new List<Message>();
        if (root != null) result.Add(root);
        result.AddRange(replies);
        return Task.FromResult(result);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing != null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

@using sv_1e8c69debc7242e995fe0dd922328e23.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-name-row">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="unread-badge">@Channel.UnreadCount</span>
        }
    </div>
    <div class="channel-description">@TruncatedDescription</div>
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<Channel> OnSelected { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 40
            ? Channel.Description[..37] + "..."
            : Channel.Description;

    private async Task OnClick() => await OnSelected.InvokeAsync(Channel);
}

@using sv_1e8c69debc7242e995fe0dd922328e23.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int ActiveChannelId { get; set; }
    [Parameter] public EventCallback<Channel> OnChannelSelected { get; set; }
}

@using sv_1e8c69debc7242e995fe0dd922328e23.Services

<div class="message-item" @onmouseenter="() => _hovering = true" @onmouseleave="() => { _hovering = false; _showEmojiPicker = false; }">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reaction-bar">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (_hovering)
    {
        <div class="message-actions">
            <button class="action-btn" title="Reply in thread" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">💬 Reply</button>
            <button class="action-btn" title="Add reaction" @onclick="ToggleEmojiPicker">😀 React</button>
        </div>

        @if (_showEmojiPicker)
        {
            <div class="emoji-picker">
                @foreach (var emoji in _commonEmojis)
                {
                    <button class="emoji-btn" @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _hovering;
    private bool _showEmojiPicker;

    private static readonly string[] _commonEmojis = { "👍", "❤️", "😂", "🎉", "🚀", "👀" };

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return sentAt.ToString("MMM d, h:mm tt");
    }
}

@using sv_1e8c69debc7242e995fe0dd922328e23.Services
@inject IJSRuntime JS

<div class="message-list" @ref="_listRef">
    @if (_loadingOlder)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    @if (HasMoreMessages)
    {
        <button class="load-more-btn" @onclick="LoadOlder" disabled="@_loadingOlder">
            ↑ Load older messages
        </button>
    }
    @foreach (var msg in Messages)
    {
        <MessageItem Message="msg"
                     ReplyCount="GetReplyCount(msg.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
    <div @ref="_bottomRef"></div>
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ReplyCounts { get; set; } = new();
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private ElementReference _listRef;
    private ElementReference _bottomRef;
    private bool _loadingOlder;

    private int GetReplyCount(int messageId) =>
        ReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task LoadOlder()
    {
        _loadingOlder = true;
        await OnLoadOlder.InvokeAsync();
        _loadingOlder = false;
    }
}

@using sv_1e8c69debc7242e995fe0dd922328e23.Services

<div class="message-area">
    @if (Channel != null)
