namespace sv_1e8c69debc7242e995fe0dd922328e23.Services;

public class MockChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId = 100;

    public MockChatService()
    {
        _channels = new List<Channel>
        {
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering topics and code reviews", 0),
            new(3, "design", "UI/UX design discussions", 1),
            new(4, "random", "Off-topic conversations", 5),
            new(5, "announcements", "Important team announcements", 0),
        };

        _messages = new List<Message>
        {
            new(1, 1, "Alice", "Hey everyone! Welcome to the new team chat.", DateTime.UtcNow.AddHours(-5), null, new List<Reaction> { new("👋", new List<string> { "Bob", "Carol" }), new("🎉", new List<string> { "Dave" }) }),
            new(2, 1, "Bob", "Thanks Alice! Excited to be here.", DateTime.UtcNow.AddHours(-4), null, new List<Reaction>()),
            new(3, 1, "Carol", "Does anyone have the link to the design docs?", DateTime.UtcNow.AddHours(-3), null, new List<Reaction> { new("👍", new List<string> { "Alice" }) }),
            new(4, 1, "Alice", "Sure, I'll share it in the design channel.", DateTime.UtcNow.AddHours(-3).AddMinutes(5), 3, new List<Reaction>()),
            new(5, 1, "Dave", "The sprint planning is at 2pm today.", DateTime.UtcNow.AddMinutes(-45), null, new List<Reaction> { new("👀", new List<string> { "Alice", "Bob", "Carol" }) }),
            new(6, 1, "Bob", "I'll be there!", DateTime.UtcNow.AddMinutes(-30), 5, new List<Reaction>()),
            new(7, 1, "Carol", "Same here. Can we discuss the API changes?", DateTime.UtcNow.AddMinutes(-20), 5, new List<Reaction>()),
            new(8, 1, "Alice", "Has anyone reviewed PR #142?", DateTime.UtcNow.AddMinutes(-10), null, new List<Reaction>()),
            new(9, 1, "Dave", "Looking at it now.", DateTime.UtcNow.AddMinutes(-5), 8, new List<Reaction>()),
            new(10, 2, "Bob", "Just pushed the new API endpoint for user search.", DateTime.UtcNow.AddHours(-2), null, new List<Reaction> { new("🚀", new List<string> { "Alice", "Carol" }) }),
            new(11, 2, "Carol", "Nice work! I'll integrate it with the frontend.", DateTime.UtcNow.AddHours(-1), null, new List<Reaction>()),
            new(12, 3, "Dave", "Here are the new mockups for the dashboard.", DateTime.UtcNow.AddHours(-6), null, new List<Reaction> { new("😍", new List<string> { "Alice", "Bob" }), new("👍", new List<string> { "Carol" }) }),
        };
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        return Task.FromResult(_channels.ToList());
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var messages = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();
        return Task.FromResult(messages);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = Interlocked.Increment(ref _nextMessageId);
        var message = new Message(id, channelId, "You", content, DateTime.UtcNow, replyToId, new List<Reaction>());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        var replies = _messages.Where(m => m.ReplyToId == rootMessageId).OrderBy(m => m.SentAt).ToList();
        var result = new List<Message>();
        if (root != null) result.Add(root);
        result.AddRange(replies);
        return Task.FromResult(result);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing != null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

