@page "/chat"
@using sv_1e8c69debc7242e995fe0dd922328e23.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannel?.Id ?? 0"
                    OnChannelSelected="SelectChannel" />

    <div class="main-content @(_threadOpen ? "with-thread" : "")">
        <MessageArea Channel="_activeChannel"
                     Messages="_messages"
                     ReplyCounts="_replyCounts"
                     HasMoreMessages="_hasMoreMessages"
                     OnLoadOlder="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />

        @if (_threadOpen)
        {
            <ThreadPanel Messages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        }
    </div>
</div>

@code {
    private List<Channel> _channels = new();
    private Channel? _activeChannel;
    private List<Message> _messages = new();
    private Dictionary<int, int> _replyCounts = new();
    private bool _hasMoreMessages;
    private const int PageSize = 20;
    private int _loadedCount;

    private bool _threadOpen;
    private int _activeThreadRootId;
    private List<Message> _threadMessages = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _activeChannel = channel;
        _loadedCount = 0;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _loadedCount = _messages.Count;
        _hasMoreMessages = _messages.Count == PageSize;

        await UpdateReplyCounts();
        await ChatService.MarkChannelReadAsync(channel.Id);
        _channels = await ChatService.GetChannelsAsync();

        CloseThreadSync();
    }

    private async Task LoadOlderMessages()
    {
        if (_activeChannel == null) return;
        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _loadedCount, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _loadedCount += older.Count;
            _hasMoreMessages = older.Count == PageSize;
            await UpdateReplyCounts();
        }
        else
        {
            _hasMoreMessages = false;
        }
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel == null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _activeThreadRootId = rootMessageId;
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThreadSync()
    {
        _threadOpen = false;
        _threadMessages = new();
        _activeThreadRootId = 0;
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel == null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannel.Id, content, _activeThreadRootId);
        _threadMessages.Add(reply);
        await UpdateReplyCounts();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reactions
        if (_activeChannel != null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _loadedCount);
        }

        if (_threadOpen)
        {
            _threadMessages = await ChatService.GetThreadAsync(_activeThreadRootId);
        }
    }

    private async Task UpdateReplyCounts()
    {
        _replyCounts.Clear();
        foreach (var msg in _messages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            var replyCount = thread.Count - 1; // exclude root
            if (replyCount > 0)
            {
                _replyCounts[msg.Id] = replyCount;
            }
        }
    }
}

