/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d23;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #2d3039;
}

::deep .sidebar-header {
    padding: 16px 16px 12px;
    border-bottom: 1px solid #2d3039;
}

::deep .sidebar-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    transition: background 0.15s;
    border-left: 3px solid transparent;
}

::deep .channel-item:hover {
    background: #2d3039;
}

::deep .channel-item.active {
    background: #2d3039;
    border-left-color: #5865f2;
}

::deep .channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.9rem;
    color: #ddd;
}

::deep .channel-item.active .channel-name {
    color: #fff;
    font-weight: 600;
}

::deep .unread-badge {
    background: #ed4245;
    color: white;
    border-radius: 10px;
    padding: 1px 7px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #888;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ===== Main Content ===== */
.main-content {
    flex: 1;
    display: flex;
    min-width: 0;
}

.main-content.with-thread ::deep .message-area {
    flex: 0 0 68%;
}

/* ===== Message Area ===== */
::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

::deep .message-area-header {
    padding: 14px 20px;
    border-bottom: 1px solid #e5e7eb;
    background: #fafbfc;
}

::deep .message-area-header h4 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #111;
}

::deep .channel-desc {
    font-size: 0.8rem;
    color: #666;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 1rem;
}

/* ===== Message List ===== */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .load-more-btn {
    display: block;
    margin: 0 auto 16px;
    background: none;
    border: 1px solid #d1d5db;
    color: #5865f2;
    padding: 6px 16px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.8rem;
}

::deep .load-more-btn:hover {
    background: #f3f4ff;
}

::deep .loading-indicator {
    text-align: center;
    padding: 10px;
    color: #888;
    font-size: 0.85rem;
}

/* ===== Message Item ===== */
::deep .message-item {
    position: relative;
    padding: 10px 12px;
    border-radius: 8px;
    margin-bottom: 4px;
    transition: background 0.1s;
}

::deep .message-item:hover {
    background: #f8f9fa;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 3px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #111;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #999;
}

::deep .message-content {
    font-size: 0.9rem;
    color: #333;
    line-height: 1.45;
}

/* ===== Reactions ===== */
::deep .reaction-bar {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #f0f1ff;
    border: 1px solid #d4d7ff;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: default;
}

/* ===== Thread Link ===== */
::deep .thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 4px;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* ===== Hover Actions ===== */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    z-index: 10;
}

